// TypeScript declaration stubs for proto/config/v1/auth.proto
// These declarations provide type information for the Bazel build environment.
// The full implementation is generated by ts-proto via `make gen`.

export interface SecretValue {
  plainText?: string;
  environmentVariable?: string;
  filePath?: string;
  remoteContent?: RemoteContent;
  vault?: VaultSecret;
  awsSecretManager?: AwsSecretManagerSecret;
  validationRegex?: string;
  /** @deprecated UI-only field for referencing a secret by ID */
  secretId?: string;
}

export interface RemoteContent {
  httpUrl?: string;
  auth?: Authentication;
}

export interface VaultSecret {
  address?: string;
  token?: SecretValue;
  path?: string;
  key?: string;
}

export interface AwsSecretManagerSecret {
  secretId?: string;
  jsonKey?: string;
  versionStage?: string;
  versionId?: string;
  region?: string;
  profile?: string;
}

export declare enum APIKeyAuth_Location {
  UNSPECIFIED = 0,
  HEADER = 1,
  QUERY = 2,
  COOKIE = 3,
}

export interface APIKeyAuth {
  paramName?: string;
  in?: APIKeyAuth_Location;
  value?: SecretValue;
  verificationValue?: string;
}

export interface BearerTokenAuth {
  token?: SecretValue;
}

export interface BasicAuth {
  username?: string;
  password?: SecretValue;
  passwordHash?: string;
}

export interface OAuth2Auth {
  tokenUrl?: string;
  clientId?: SecretValue;
  clientSecret?: SecretValue;
  scopes?: string;
  issuerUrl?: string;
  audience?: string;
  authorizationUrl?: string;
}

export interface OIDCAuth {
  issuer?: string;
  subject?: string;
  email?: string;
  audience?: string[];
}

export interface MTLSAuth {
  clientCertPath?: string;
  clientKeyPath?: string;
  caCertPath?: string;
}

export interface TrustedHeaderAuth {
  headerName?: string;
  headerValue?: string;
}

export interface Authentication {
  apiKey?: APIKeyAuth;
  bearerToken?: BearerTokenAuth;
  basicAuth?: BasicAuth;
  oauth2?: OAuth2Auth;
  oidc?: OIDCAuth;
  mtls?: MTLSAuth;
  trustedHeader?: TrustedHeaderAuth;
}

export interface UserToken {
  userId?: string;
  serviceId?: string;
  accessToken?: string;
  refreshToken?: string;
  tokenType?: string;
  expiry?: string;
  scope?: string;
}

export interface Credential {
  id: string;
  name: string;
  authentication?: Authentication;
  token?: UserToken;
}
